FusedMoEExpertsFwdOp:
  family: moe
  status: implemented
  ref_api: workloads.moe.ref_routed_experts
  signature:
    forall: {T: Dim, H: Dim, F: Dim, E: Dim, K: Dim, D: "DType[float16 | bfloat16]"}
    params:
      routed_scaling_factor: {type: float, default: 1.0}
      # MoEGroupedGEMMFwdOp's docstring defines each activation and the order of w_gate_up's
      # gate and up rows it reads.
      activation: {type: "'silu_and_mul' | 'gelu_and_mul' | 'swigluoai'", default: silu_and_mul, kw_only: true}
    inputs:
      hidden_states: {dtype: D, shape: "[T, H]", contiguous: true}
      w_gate_up: {dtype: D, shape: "[E, 2 * F, H]", contiguous: true}
      w_down: {dtype: D, shape: "[E, H, F]", contiguous: true}
      topk_weights: {dtype: float32, shape: "[T, K]", contiguous: true}
      topk_ids: {dtype: int32, shape: "[T, K]", contiguous: true, values: "topk_ids(T, K, E)", requires: ["in_range(0, E)"]}
      # Per-expert biases: b_gate_up, in w_gate_up's row order, is added to the gate/up GEMM result
      # before the activation; b_down to the down GEMM result before the routing weight scales it,
      # out[t] = sum_k w[t, k] * (down_k(h) + b_down[k]).
      b_gate_up: {dtype: D, shape: "[E, 2 * F]", type: "Tensor | None", default: null, contiguous: true}
      b_down: {dtype: D, shape: "[E, H]", type: "Tensor | None", default: null, contiguous: true}
    outputs:
      # The expert MLP has read its inputs before the weighted reduction writes `out`.
      output: {dtype: D, shape: "[T, H]", buffer: out, contiguous: true, overlaps: [hidden_states, w_gate_up, w_down, topk_ids, b_gate_up, b_down]}
    shape_rules:
    - "T > 0"
    - "K > 0"
    - "H > 0"
    - "F > 0"
    - "routed_scaling_factor > 0"
  workloads:
    # Qwen3-235B-A22B: H=4096, F=1536, E=128, K=8
  - {T: 512, E: 128, K: 8, H: 4096, F: 1536, dtype_cases: [{D: float16}, {D: bfloat16}], label: "qwen3-235b-decode"}
  - {T: 4096, E: 128, K: 8, H: 4096, F: 1536, dtype_cases: [{D: float16}, {D: bfloat16}], label: "qwen3-235b-prefill"}
    # DeepSeek-V3: H=7168, F=2048, E=256, K=8
  - {T: 512, E: 256, K: 8, H: 7168, F: 2048, dtype_cases: [{D: float16}, {D: bfloat16}], label: "ds-v3-decode"}
  - {T: 4096, E: 256, K: 8, H: 7168, F: 2048, dtype_cases: [{D: float16}, {D: bfloat16}], label: "ds-v3-prefill"}
