import json,glob,os
agg={}
for f in glob.glob('examples/*/.migration_state.json'):
    d=json.load(open(f)); agg[os.path.dirname(f)]=d
for op,ad in sorted(agg.items()):
    print(f"\n## {ad.get('op_name')}  phase={ad.get('phase')}  funcs={ {k:v.get('status') for k,v in ad.get('functions',{}).items()} }")
    for fn in ad.get('functions',{}):
        p=f"{op}/{fn}/.stage_state.json"
        if os.path.exists(p):
            s=json.load(open(p))
            ss=s.get('stage_status',{})
            print(f"   {fn:32s} phase={s.get('phase'):9s} stages={ss} retry={s.get('retry_count')} s3_fail={s.get('stage3_failure_breakdown')}")
    print("   integration:",ad.get('integration'))
EOF

